extern "C" natl c_ceasyncread_n(natl id, char *buf, natl quanti)
{
    // Validate id
    if (id >= next_ce) {
        abort_p();
    }

    // Validate quanti
    if (!quanti) {
        abort_p();
    }

    // Check for Trojan Horse and buffer validity
    if (!access(buf, quanti, true, true)) {
        abort_p();
    }

    des_ce *ce = &array_ce[id];

    // Acquire mutex
    sem_wait(ce->mutex);

    // Find a free descriptor
    natl free = 0xFFFFFFFF;
    for (natl i = 0; i < MAX_CE_ASYNC; i++) {
        if (!ce->tr[i].buf) {
            free = i;
            break;
        }
    }

    // If no free descriptor, return error
    if (free == 0xFFFFFFFF) {
        sem_signal(ce->mutex);
        return 0xFFFFFFFF;
    }

    // Set up the descriptor
    ce->tr[free].buf = buf;
    ce->tr[free].quanti = quanti;
    ce->tr[free].next = 0xFFFFFFFF;

    // Link it into the queue
    if (ce->last == 0xFFFFFFFF) {
        ce->last = free;
    } else {
        ce->tr[ce->last].next = free;
        ce->last = free;
    }

    // If no active transfer, start this one
    if (ce->cur == 0xFFFFFFFF) {
        ce->cur = free;
        // Enable interrupts on the peripheral
        outputb(inputb(ce->iCTL) | 2, ce->iCTL);  // Set bit 1
    }

    sem_signal(ce->mutex);
    return free;
}
```

